}, {"title": "Cardiac cycle"}, {"title": "ECG"}, {"title": "Double circulation"}]}, {"title": "Control", "concepts": [{"title": "Regulation of cardiac activity"}, {"title": "Circulatory disorders"}]}]}, {"number": 16, "title": "Excretory Products and their Elimination", "topics": [{"title": "Waste removal", "concepts": [{"title": "Ammonotelism ureotelism and uricotelism"}, {"title": "Human excretory system"}]}, {"title": "Nephron", "concepts": [{"title": "Ultrafiltration"}, {"title": "Selective reabsorption"}, {"title": "Secretion"}, {"title": "Urine concentration"}]}, {"title": "Regulation", "concepts": [{"title": "Kidney regulation"}, {"title": "Micturition"}, {"title": "Excretory disorders and dialysis"}]}]}, {"number": 17, "title": "Locomotion and Movement", "topics": [{"title": "Movement", "concepts": [{"title": "Types of movement"}, {"title": "Skeletal muscle structure"}, {"title": "Sliding filament mechanism"}]}, {"title": "Support", "concepts": [{"title": "Skeletal system"}, {"title": "Joints"}, {"title": "Muscular and skeletal disorders"}]}]}, {"number": 18, "title": "Neural Control and Coordination", "topics": [{"title": "Neural signalling", "concepts": [{"title": "Neuron structure"}, {"title": "Resting potential"}, {"title": "Action potential"}, {"title": "Synaptic transmission"}]}, {"title": "Nervous systems", "concepts": [{"title": "Central nervous system"}, {"title": "Peripheral nervous system"}]}]}, {"number": 19, "title": "Chemical Coordination and Integration", "topics": [{"title": "Endocrine system", "concepts": [{"title": "Hormone signalling"}, {"title": "Hypothalamus and pituitary"}, {"title": "Pineal thyroid and parathyroid"}, {"title": "Thymus and adrenal glands"}, {"title": "Pancreas"}, {"title": "Gonadal hormones"}]}, {"title": "Integration", "concepts": [{"title": "Other hormone-producing tissues"}, {"title": "Mechanism of hormone action"}, {"title": "Endocrine feedback"}]}]}]}]}]}$manifest$;
s jsonb;b jsonb;h jsonb;t jsonb;c jsonb;vid uuid;bid uuid;hid uuid;tid uuid;ci integer;ti integer;begin
for s in select * from jsonb_array_elements(doc->'subjects') loop
 insert into public.academic_curriculum_versions(board,academic_year,class_level,subject,official_source,status,streams)
 values(doc->>'board',doc->>'academic_year',11,s->>'subject',s->'books'->0->>'official_source_url','candidate',
 case when s->>'subject'='Biology' then array['pcb','pcmb'] when s->>'subject'='Mathematics' then array['pcm','pcmb','commerce'] else array['pcm','pcb','pcmb'] end)
 on conflict(board,academic_year,class_level,subject) do nothing;
 select id into strict vid from public.academic_curriculum_versions where board=doc->>'board' and academic_year=doc->>'academic_year' and class_level=11 and subject=s->>'subject';
 update public.academic_curriculum_versions set catalog_visible=true,catalog_metadata=jsonb_build_object('curriculum_version',doc->>'version','chapter_verification',doc->>'chapter_verification','classification_verification','pending','last_verified_at',doc->>'checked_at') where id=vid;
 for b in select * from jsonb_array_elements(s->'books') loop
  insert into public.academic_books(curriculum_id,title,part,official_source_url,last_verified_at) values(vid,b->>'title',b->>'part',b->>'official_source_url',(doc->>'checked_at')::timestamptz) on conflict(curriculum_id,title,part) do nothing;
  select id into strict bid from public.academic_books where curriculum_id=vid and title=b->>'title' and part=b->>'part';
  for h in select * from jsonb_array_elements(b->'chapters') loop
   insert into public.academic_chapters(curriculum_id,position,title,source_url,book_id) values(vid,(h->>'number')::integer,h->>'title',b->>'official_source_url',bid) on conflict(curriculum_id,title) do nothing;
   select id into strict hid from public.academic_chapters where curriculum_id=vid and title=h->>'title';
   update public.academic_chapters set book_id=bid,metadata=metadata||jsonb_build_object('verification_status','official_contents_checked','last_verified_at',doc->>'checked_at','curriculum_version',doc->>'version') where id=hid;
   ci:=0;ti:=0;
   for t in select * from jsonb_array_elements(h->'topics') loop
    ti:=ti+1;
    insert into public.academic_topics(chapter_id,title,position,metadata) values(hid,t->>'title',ti,jsonb_build_object('verification_status','pending','classification','TIPIX editorial outline')) on conflict(chapter_id,title) do nothing;
    select id into strict tid from public.academic_topics where chapter_id=hid and title=t->>'title';
    for c in select * from jsonb_array_elements(t->'concepts') loop
     ci:=ci+1;
     insert into public.academic_concepts(curriculum_id,chapter_title,concept_title,subtopic,position,topic_id,classification_reference)
     values(vid,h->>'title',c->>'title',t->>'title',ci,tid,jsonb_build_object('verification_status','pending','classification','TIPIX editorial outline','official_source_url',b->>'official_source_url','curriculum_version',doc->>'version'))
     on conflict(curriculum_id,chapter_title,concept_title) do nothing;
    end loop;
   end loop;
  end loop;
 end loop;
end loop;
end $import$;

-- Metadata-only catalogue. Draft answer keys and lesson blocks never leave the review APIs.
create or replace function tipix_private.curriculum_catalog() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); g integer; st text; evidence jsonb;
begin
 if uid is null or not tipix_private.verified_account() then raise exception 'Sign in with a verified account';end if;
 select grade,stream into g,st from public.tipix_student_profiles where id=uid;
 if g is null then raise exception 'Student profile required';end if;
 evidence:=tipix_private.academic_api('overview','{}')->'concepts';
 return (select coalesce(jsonb_agg(jsonb_build_object(
  'id',v.id,'subject',v.subject,'class_level',v.class_level,'academic_year',v.academic_year,'board',v.board,'metadata',v.catalog_metadata,
  'in_study_plan',v.streams is null or coalesce(st,'general')=any(v.streams),
  'books',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'title',b.title,'part',b.part,'source_url',b.official_source_url) order by b.part),'[]') from public.academic_books b where b.curriculum_id=v.id),
  'chapters',(select coalesce(jsonb_agg(jsonb_build_object('id',h.id,'title',h.title,'position',h.position,'book_id',h.book_id,'source_url',h.source_url,'metadata',h.metadata,
    'topics',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'position',t.position,'metadata',t.metadata) order by t.position,t.title),'[]') from public.academic_topics t where t.chapter_id=h.id),
    'concepts',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.concept_title,'topic_id',c.topic_id,'subtopic',c.subtopic,'position',c.position,'classification',c.classification_reference,
      'lesson_available',c.published and v.status='published' and (v.streams is null or coalesce(st,'general')=any(v.streams)) and exists(select 1 from public.academic_learning_tasks l where l.concept_id=c.id),
      'question_count',(select count(*) from public.academic_verified_question_bank q where q.concept_id=c.id and q.is_published and q.is_verified),
      'mastery',(select e->'mastery' from jsonb_array_elements(evidence) e where e->>'concept_id'=c.id::text limit 1)
    ) order by c.position,c.concept_title),'[]') from public.academic_concepts c where c.curriculum_id=v.id and c.chapter_title=h.title)
  ) order by h.position),'[]') from public.academic_chapters h where h.curriculum_id=v.id)
 ) order by v.subject,v.academic_year desc),'[]') from public.academic_curriculum_versions v where v.class_level=g and (v.catalog_visible or v.status='published'));
end $$;
revoke all on function tipix_private.curriculum_catalog() from public,anon;
grant execute on function tipix_private.curriculum_catalog() to authenticated;
create or replace function public.curriculum_catalog() returns jsonb language sql security invoker set search_path='' as $$ select tipix_private.curriculum_catalog() $$;
revoke all on function public.curriculum_catalog() from public,anon;
grant execute on function public.curriculum_catalog() to authenticated;
